describe('Phone Number Field - Numeric Input Validation', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('[data-testid="phone-input"]').as('phoneInput');
  });

  it('should accept only numeric characters in phone number field', () => {
    cy.get('@phoneInput').type('1234567890');
    cy.get('@phoneInput').should('have.value', '1234567890');
  });

  it('should reject non-numeric characters and only display numbers', () => {
    cy.get('@phoneInput').type('123abc456def789');
    cy.get('@phoneInput').should('have.value', '123456789');
  });

  it('should handle special characters and symbols in phone input', () => {
    cy.get('@phoneInput').type('123-456-7890');
    cy.get('@phoneInput').should('have.value', '1234567890');
  });

  it('should reject letters and special symbols completely', () => {
    cy.get('@phoneInput').type('!@#$%^&*()');
    cy.get('@phoneInput').should('have.value', '');
  });

  it('should allow leading zeros in phone number', () => {
    cy.get('@phoneInput').type('0123456789');
    cy.get('@phoneInput').should('have.value', '0123456789');
  });

  it('should handle paste events with mixed alphanumeric content', () => {
    const mixedContent = 'Phone: 555-1234-ABC';
    cy.get('@phoneInput').invoke('val', mixedContent).trigger('input');
    cy.get('@phoneInput').should('have.value', '5551234');
  });

  it('should maintain cursor position when rejecting invalid characters', () => {
    cy.get('@phoneInput').type('123');
    cy.get('@phoneInput').type('a');
    cy.get('@phoneInput').should('have.value', '123');
    cy.get('@phoneInput').type('456');
    cy.get('@phoneInput').should('have.value', '123456');
  });

  it('should handle rapid input of mixed valid and invalid characters', () => {
    cy.get('@phoneInput').type('1a2b3c4d5e6f7g8h9i0j');
    cy.get('@phoneInput').should('have.value', '1234567890');
  });

  it('should reject whitespace characters in phone number', () => {
    cy.get('@phoneInput').type('123 456 7890');
    cy.get('@phoneInput').should('have.value', '1234567890');
  });

  it('should handle maximum length constraint with numeric input only', () => {
    cy.get('@phoneInput').invoke('attr', 'maxlength').then((maxLength) => {
      if (maxLength) {
        const longNumber = '1'.repeat(parseInt(maxLength) + 5);
        cy.get('@phoneInput').type(longNumber);
        cy.get('@phoneInput').invoke('val').then((value) => {
          expect(value.length).to.be.lte(parseInt(maxLength));
        });
      }
    });
  });

  it('should display validation error message for non-numeric input attempt', () => {
    cy.get('@phoneInput').type('abc');
    cy.get('[data-testid="phone-error"]').should('be.visible');
    cy.get('[data-testid="phone-error"]').should('contain', 'only numeric');
  });

  it('should clear validation error when valid numeric input is provided', () => {
    cy.get('@phoneInput').type('abc');
    cy.get('[data-testid="phone-error"]').should('be.visible');
    cy.get('@phoneInput').clear();
    cy.get('@phoneInput').type('1234567890');
    cy.get('[data-testid="phone-error"]').should('not.exist');
  });
});
